1	// THE TARGET — which pull request a run works on (tasks-dispatch DESIGN §6.4b,
2	// decision §15.32). A task's `expected_outcome` says what its run does to pull
3	// requests; the executor resolves that into a concrete branch and pull request
4	// ONCE, after the precondition said go and before code-work, and hands the
5	// answer to both phases (code-work as environment, the agent as item fields).
6	// Neither phase discovers, chooses or disposes of a pull request on its own —
7	// that was three independent decisions in three places, and a task could not
8	// even say "append to my open pull request".
9	//
10	// A task's open pull requests are recognised two ways, either sufficient: the
11	// branch prefix this module mints (`claudinite/<pack>/<task>/`), or the
12	// `Claudinite-Task:` trailer on the pull request's head commit — the authority the
13	// movement signals already read, which is what still finds a pull request a lane
14	// opened under its own branch name before the executor minted them.
15	//
16	// `planTarget` is pure over what was read; `resolveTarget` is the I/O shell that
17	// reads it. A read the shell cannot make is `{ error }` — a run failure the
18	// executor parks, never a guess: an unreadable pull request list looks exactly
19	// like an empty one, and "nothing to amend" on that evidence stacks a duplicate.
20	
21	import { pullDisposition } from '../land-pr.mjs';
22	import { taskFromMessage, taskTrailer } from '../task-trailer.mjs';
23	import { canonicalOutcome, opensPullRequest } from '../task-contract.mjs';
24	
25	export const TARGET_MODES = Object.freeze(['none', 'fresh', 'amend']);
26	
27	// Every branch the executor mints lives under one root, and every task under its
28	// own prefix beneath it — which is what makes the prefix a family, not a guess.
29	export const BRANCH_ROOT = 'claudinite';
30	export const taskBranchPrefix = (taskId) => `${BRANCH_ROOT}/${taskId}/`;
31	
32	// One branch per run, dated and seeded: two runs on one day must not collide, and
33	// a name that carries its date is one a person can read a week later.
34	export const mintBranch = (taskId, now, seed) =>
35	  `${taskBranchPrefix(taskId)}${new Date(now).toISOString().slice(0, 10)}-${seed}`;
36	export const newSeed = () => Math.random().toString(36).slice(2, 8);
37	
38	// This task's open pull requests, newest first. `headTaskOf(pr)` answers which task
39	// the pull request's head commit names, for the ones the prefix does not settle.
40	export function taskPullsOf(pulls, taskId, headTaskOf = () => null) {
41	  const prefix = taskBranchPrefix(taskId);
42	  return (pulls ?? [])
43	    .filter((p) => String(p?.head?.ref ?? '').startsWith(prefix) || headTaskOf(p) === taskId)
44	    .sort((a, b) => b.number - a.number);
45	}
46	
47	// What a target becomes in code-work's environment — three variables in every
48	// mode, so a worker can tell "no target" from "an executor that sets none".
49	export const targetEnv = (target) => ({
50	  CLAUDINITE_TARGET_MODE: target?.mode ?? 'none',
51	  CLAUDINITE_TARGET_BRANCH: target?.branch ?? '',
52	  CLAUDINITE_TARGET_PR: target?.pr == null ? '' : String(target.pr),
53	});
54	
55	// The decision, pure. `incumbents` are this task's open pull requests newest
56	// first; `mergeable` is the newest one's answer where the outcome amends;
57	// `disposition` is `pullDisposition`'s verdict on the newest where the outcome
58	// supersedes, with `merge` meaning the shell already landed it.
59	//
60	//   { mode, branch, pr, supersedes, landed, reason }
61	//   mode      — 'none' | 'fresh' | 'amend'
62	//   branch    — the branch the run pushes to (null under 'none')
63	//   pr        — the pull request an amend pushes onto (null otherwise)
64	//   supersedes — pull requests to close once this run's own exists
65	//   landed    — the incumbent the shell merged, whose landing ends this occurrence
66	export function planTarget({ outcome, incumbents = [], mergeable = null, disposition = null, branch }) {
67	  const canonical = canonicalOutcome(outcome);
68	  if (!canonical) throw new Error(`"${outcome}" is not a legal outcome ceiling`);
69	  const none = (reason) => ({ mode: 'none', branch: null, pr: null, supersedes: [], landed: null, reason });
70	  const fresh = (reason) => ({ mode: 'fresh', branch, pr: null, supersedes: [], landed: null, reason });
71	  const newest = incumbents[0] ?? null;
72	
73	  if (!opensPullRequest(canonical)) return none('this task changes no code');
74	  if (canonical === 'fresh_pr') return fresh('a fresh branch; earlier pull requests of this task are left as they are');
75	
76	  if (canonical === 'amend_existing_or_create_new_pr') {
77	    if (!newest) return fresh('no open pull request of this task to amend');
78	    if (mergeable === true) {
79	      return {
80	        mode: 'amend', branch: newest.head.ref, pr: newest.number, supersedes: [], landed: null,
81	        reason: `amending #${newest.number}, which has no conflicts with its base`,
82	      };
83	    }
84	    if (mergeable === false) return fresh(`#${newest.number} has conflicts with its base, so this run takes a fresh branch`);
85	    return fresh(`#${newest.number}'s mergeability could not be read, so this run takes a fresh branch rather than push onto it`);
86	  }
87	
88	  // supersede_existing_pr
89	  if (!newest) return fresh('no open pull request of this task to supersede');
90	  const numbers = incumbents.map((p) => p.number);
91	  if (disposition === 'merge') {
92	    // The previous delivery had concluded green and was never landed — the exact
93	    // member whose CI outruns the landing budget every day, which the next-cycle
94	    // disposal used to rescue. Landing it is finishing this task's own delivery;
95	    // the tree this run holds predates that merge, so the occurrence ends here and
96	    // the next one converges from the moved base.
97	    return {
98	      ...none(`landed #${newest.number}, this task's previous delivery, which had concluded green — the occurrence ends there`),
99	      landed: newest.number, supersedes: numbers.slice(1),
100	    };
101	  }
102	  return {
103	    mode: 'fresh', branch, pr: null, supersedes: numbers, landed: null,
104	    reason: `a fresh branch; ${numbers.map((n) => `#${n}`).join(', ')} close as superseded once this run's pull request exists`,
105	  };
106	}
107	
108	const defaultSleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
109	
110	// GitHub computes `mergeable` lazily: the first read after a push answers null
111	// while it works. Three reads two seconds apart cover the documented delay; an
112	// answer that never comes plans as unknown, which takes a fresh branch.
113	const MERGEABLE_READS = 3;
114	const MERGEABLE_WAIT_MS = 2000;
115	
116	async function deleteRef(gh, repo, ref, log) {
117	  if (!ref) return;
118	  const res = await gh(`/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
119	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
120	}
121	
122	// The I/O shell. Reads nothing for the two outcomes that involve no existing pull
123	// request; for the other two, lists the open pull requests, recognises this
124	// task's, and reads exactly what the plan needs of the newest — its mergeability
125	// for an amend, the runs on its head for a supersede (landing it there when
126	// `delivery` allows and the runs concluded green).
127	export async function resolveTarget({
128	  gh, repo, taskId, outcome, delivery, now, seed = newSeed(), sleep = defaultSleep, log = console.log,
129	}) {
130	  const canonical = canonicalOutcome(outcome);
131	  if (!canonical) return { error: `"${outcome}" is not a legal outcome ceiling` };
132	  const branch = mintBranch(taskId, now, seed);
133	  if (canonical === 'no_code_changes' || canonical === 'fresh_pr') return planTarget({ outcome: canonical, incumbents: [], branch });
134	
135	  const listed = await gh(`/repos/${repo}/pulls?state=open&per_page=100`);
136	  if (listed.status !== 200 || !Array.isArray(listed.json)) {
137	    return { error: `could not list the open pull requests in ${repo} (${listed.status}) — an unreadable list is not an empty one` };
138	  }
139	  // One head-commit read per open pull request the prefix does not settle: the
140	  // trailer is what still recognises a pull request a lane opened under its own
141	  // branch name before the executor minted them.
142	  const prefix = taskBranchPrefix(taskId);
143	  const heads = new Map();
144	  for (const p of listed.json) {
145	    if (String(p?.head?.ref ?? '').startsWith(prefix) || !p?.head?.sha) continue;
146	    const res = await gh(`/repos/${repo}/commits/${p.head.sha}`);
147	    heads.set(p.number, res.status === 200 ? taskFromMessage(res.json?.commit?.message) : null);
148	  }
149	  const incumbents = taskPullsOf(listed.json, taskId, (p) => heads.get(p.number) ?? null);
150	  const newest = incumbents[0] ?? null;
151	  if (!newest) return planTarget({ outcome: canonical, incumbents, branch });
152	
153	  if (canonical === 'amend_existing_or_create_new_pr') {
154	    let mergeable = null;
155	    for (let n = 0; n < MERGEABLE_READS; n += 1) {
156	      if (n) await sleep(MERGEABLE_WAIT_MS);
157	      const res = await gh(`/repos/${repo}/pulls/${newest.number}`);
158	      if (res.status !== 200) break;
159	      if (typeof res.json?.mergeable === 'boolean') { mergeable = res.json.mergeable; break; }
160	    }
161	    return planTarget({ outcome: canonical, incumbents, mergeable, branch });
162	  }
163	
164	  // supersede_existing_pr — judged by the runs on the newest incumbent's head,
165	  // exactly as the next-cycle disposal judged it. An unreadable head is `close`:
166	  // the successor this run opens gets its own chance to land.
167	  const runsRes = await gh(`/repos/${repo}/actions/runs?head_sha=${newest.head?.sha ?? ''}&per_page=100`);
168	  const runs = runsRes.status === 200
169	    ? (runsRes.json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }))
170	    : null;
171	  let disposition = runs ? pullDisposition({ delivery, runs }) : 'close';
172	  if (disposition === 'merge') {
173	    const res = await gh(`/repos/${repo}/pulls/${newest.number}/merge`, {
174	      method: 'PUT', body: { merge_method: 'squash', commit_message: taskTrailer(taskId) },
175	    });
176	    if (res.status === 200) {
177	      log(`landed #${newest.number} — ${taskId}'s previous delivery had concluded green and was never merged`);
178	      await deleteRef(gh, repo, newest.head?.ref, log);
179	    } else {
180	      log(`could not land #${newest.number} (${res.status}: ${res.json?.message ?? 'no message'}) — superseding it instead`);
181	      disposition = 'close';
182	    }
183	  }
184	  return planTarget({ outcome: canonical, incumbents, disposition, branch });
185	}
186	
187	// Close the pull requests a run superseded, now that its own (`successor`) exists:
188	// a comment saying by what, the close, and the dead branch tidied. Best-effort
189	// throughout — the successor is the deliverable, and one already closed by hand,
190	// or unreadable, is logged and left.
191	export async function closeSuperseded({ gh, repo, numbers = [], successor, log = console.log }) {
192	  for (const number of numbers) {
193	    const read = await gh(`/repos/${repo}/pulls/${number}`);
194	    if (read.status !== 200) { log(`could not close #${number} (${read.status}) — leaving it`); continue; }
195	    await gh(`/repos/${repo}/issues/${number}/comments`, {
196	      method: 'POST', body: { body: `Superseded by #${successor}, a later run of the same task. Closing this one.` },
197	    });
198	    const closed = await gh(`/repos/${repo}/pulls/${number}`, { method: 'PATCH', body: { state: 'closed' } });
199	    if (closed.status !== 200) { log(`could not close #${number} (${closed.status}) — leaving it`); continue; }
200	    log(`closed #${number} — superseded by #${successor}`);
201	    await deleteRef(gh, repo, read.json?.head?.ref, log);
202	  }
203	}
