1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { existsSync } from 'node:fs';
19	import { pathToFileURL } from 'node:url';
20	import { isSuspended, readSuspendedNow, suspendedNotice, SUSPEND_ALL_VAR } from './suspend.mjs';
21	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from './heartbeat.mjs';
22	import { renderTaskExec } from '../run-record.mjs';
23	import { evaluatePreconditions } from '../precondition-policy.mjs';
24	import { windowDays } from './signals.mjs';
25	import { swapStatus, clearStatus } from './apply-status.mjs';
26	import { resolveTarget, closeSuperseded } from './target.mjs';
27	import { deliveryFor } from '../land-pr.mjs';
28	import {
29	  BLOCKED, READY, URGENT, EXECUTING, AGENT, requeueHint,
30	  STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
31	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, QUEUED_LABEL, isStandingItem,
32	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE,
33	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
34	  parseWorkItemTitle, isWorkItemTitle, parseWorkItemBody, taskIdFromPath, parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
35	  LAST_VERDICT_HEADING, lastVerdictLines,
36	  withTarget,
37	} from './work-item.mjs';
38	
39	const titleOf = (item) => (item.title ?? '').trim();
40	// An item somebody is executing — the executor holds it, or the agent it handed to
41	// does. Decoded, never a literal label test: the item may wear any engine's spelling.
42	const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
43	// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
44	// a marked issue (DESIGN §16.1) keeps its own human title and names its task in the
45	// machine block's first line, so the id comes from the task whose worker path that
46	// is. `pathTo` is that lookup, injected because only the run holds the task set.
47	const taskIdOf = (item, pathTo = () => null) => {
48	  const p = parseWorkItemTitle(item.title);
49	  if (p) return `${p.pack}/${p.task}`;
50	  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
51	};
52	
53	// The pick order (DESIGN §6.1): urgent first, then RANDOM among the ready, with
54	// two skip rules read live at pick time. Random rather than oldest-first because
55	// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
56	// a deterministic order lets one unlucky head dominate every run of a chain
57	// (DESIGN §15.20).
58	//
59	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
60	//    item executing or handed to an agent — one task, one execution at a time,
61	//    while a fan-out's distinct qualifiers still parallelize.
62	//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
63	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
64	//    A declined upstream holds nothing back — it has no item at all (a no files
65	//    only a board row, #1115) — and neither does one sitting `needs-human`: a
66	//    broken upstream must not halt its dependents indefinitely.
67	//
68	// `open` is every open work item; `taskAfter(id)` gives a task's declared
69	// upstreams as `<pack>/<task>` ids, and `frequencyOf(id)` that task's declared
70	// frequency at HEAD — which is half of what says whether an item is a standing
71	// occurrence or an ad-hoc run (§15.26). `random` is the tie-break draw, injected
72	// so a test can pin an order the production call deliberately does not have.
73	export function pickOrder(open = [], { taskAfter = () => [], frequencyOf = () => null, random = Math.random, pathTo = () => null } = {}) {
74	  const idOf = (item) => taskIdOf(item, pathTo);
75	  const live = (item) => [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT].some((s) => isStatus(item, s));
76	  const standing = (item) => isStandingItem(item, frequencyOf(idOf(item)));
77	  const liveUpstream = (upstreamId) => open.some((o) =>
78	    idOf(o) === upstreamId && standing(o) && live(o));
79	  // One draw per item, taken once: a comparator that called `random()` per
80	  // comparison would not be a consistent ordering, and `Array.sort` on one is
81	  // free to produce anything at all.
82	  const draw = new Map(open.map((i) => [i.number, random()]));
83	
84	  return open
85	    .filter((i) => isStatus(i, STATUS_READY))
86	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
87	      && running(o)))
88	    .filter((i) => {
89	      if (!standing(i)) return true;
90	      return !taskAfter(idOf(i)).some(liveUpstream);
91	    })
92	    .sort((a, b) =>
93	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
94	      || draw.get(a.number) - draw.get(b.number));
95	}
96	
97	// The claim comment carries WHO and WHEN — the executor id and its run URL —
98	// because executor identity is an unbounded set and must never become a label
99	// (DESIGN §4).
100	export const claimComment = ({ executor, runUrl, at }) =>
101	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
102	
103	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
104	// each an implicit assumption made explicit:
105	//
106	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
107	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
108	//    comment ids are server-assigned and strictly increasing — a total order the
109	//    protocol gets for free. Nothing here compares runner clocks.
110	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
111	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
112	//    and revert leaves one), and arbitrating over all of them makes a dead claim
113	//    outrank every future live claimant — the item then livelocks through reclaim
114	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
115	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
116	//    owner; it can only leave an item with no state label, which the janitor
117	//    repairs.
118	export function claimWinner(comments = []) {
119	  const sorted = [...comments].sort((a, b) => a.id - b.id);
120	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
121	  const claims = sorted
122	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
123	    .filter((c) => !boundary || c.id > boundary.id);
124	  return claims[0] ?? null;
125	}
126	
127	// After WINNING a claim, re-verify the pick filters against live state (F15). The
128	// filters read possibly-stale state, so two executors can pass them simultaneously
129	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
130	// an upstream and its dependent. The per-item lease cannot see that: it protects
131	// one item, not one title. If a conflicting item now holds an EARLIER claim
132	// (comment id — the same arbiter the lease trusts), this executor reverts its own
133	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
134	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null, pathTo = () => null } = {}) {
135	  const idOf = (i) => taskIdOf(i, pathTo);
136	  const standing = (i) => isStandingItem(i, frequencyOf(idOf(i)));
137	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
138	  return others.some((o) => {
139	    if (o.number === item.number) return false;
140	    if (!running(o)) return false;
141	    const conflicting = titleOf(o) === titleOf(item)
142	      || (upstreams.includes(idOf(o)) && standing(o));
143	    return conflicting && o.claimId != null && o.claimId < myClaimId;
144	  });
145	}
146	
147	// The no-go outcome (DESIGN §6.4, as amended by #1115): every decline CLOSES
148	// the item with the reason. The roll — `Not-before` stamped, open-blocked,
149	// waiting out the period — is gone: "asked and declined" lives on the schedule
150	// board, and a scheduled item's next occurrence is the scheduler run's ask at
151	// its next anchor (the closed-at half of the occurrence guard keeps this
152	// period consumed). `standing` marks whether the close should say so.
153	// The `(item, task, schedule, now, reason)` signature is kept — callers and
154	// fielded tests pass all five, and the standing/ad-hoc distinction still
155	// shapes the close's wording.
156	export function noGoPlan(item, task, schedule, now, reason) {
157	  return {
158	    kind: 'close',
159	    outcome: TASK_OBSOLETE,
160	    stateReason: 'not_planned',
161	    reason,
162	    standing: isStandingItem(item, task?.decl?.frequency),
163	  };
164	}
165	
166	// --- the shell ----------------------------------------------------------------
167	
168	const nowIso = () => new Date().toISOString();
169	
170	// ONE EXECUTOR RUN DRAINS THE QUEUE (DESIGN §6, §10, decision §15.30, reversing
171	// §15.22's one-item run). Actions bills each job's runtime rounded UP to the next
172	// minute, so a day's cost is the RUN count: a run that performed one item paid a
173	// whole invocation — checkout, setup, rounding — per item. So a run claims an
174	// item, sees it to its settle, then picks the next, and ends when nothing is
175	// pickable. Items still settle ONE AT A TIME: this moved the run boundary, not
176	// the occupancy model, and capacity is still executor width.
177	//
178	// What still starts a run is the enumerable list of §10, each cause on the
179	// record: the scheduler run's drain job (dispatched only when that run leaves
180	// something pickable), a label event, an agent session's close-time drain, and
181	// the workflow's failure-continuation job when a run dies mid-drain. Self-
182	// re-dispatch retired with the one-item run — the remainder is this run's own.
183	//
184	// AN ITEM THIS RUN LET GO OF IS NEVER RE-ATTEMPTED BY IT. Losing a claim race
185	// leaves the item running under its winner, so the next pick simply does not see
186	// it — but a post-claim REVERT puts the item back to ready, and re-picking what
187	// this run just returned to the queue is an unbounded loop, not a retry. Both
188	// exits are therefore recorded in `standDown` and skipped for the rest of the
189	// run; the executor that won, and the scheduler run behind it, carry those.
190	//
191	// The loop terminates because every iteration either settles an item (which
192	// leaves the ready state) or stands down from one — and the only items that
193	// newly become pickable are the dependents a close releases, which is the
194	// chaining this exists to do. Its outer bound is the workflow's own timeout.
195	//
196	// Injected seams keep the run testable end to end without GitHub, code-work
197	// subprocesses or an invocation endpoint. `heldNow` is the operator hold, asked
198	// between items (§15.30): `vars.*` reaches the env at start only, so a drain that
199	// outlives the hold's arrival can only see it by asking.
200	export async function runExecutor({
201	  gh, repo, root, config, tasks, executorId, runUrl = null,
202	  now = () => new Date(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
203	  collectSignalsFor, runTaskCodeWork, invokeAgent, heldNow = null, log = console.log,
204	  resolveTargetFor = null,
205	}) {
206	  const api = await import('../github.mjs');
207	  const { listOpenWorkItems } = await import('./read.mjs');
208	  const schedule = config.taskScheduler;
209	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
210	  const taskAfter = (id) => byId.get(id)?.decl?.schedule_after ?? [];
211	  const frequencyOf = (id) => byId.get(id)?.decl?.frequency ?? null;
212	  // A marked issue names its task by worker path, so the run needs the inverse of
213	  // the id map — built from the same task set, so a path this repo does not carry
214	  // resolves to nothing and the item is malformed rather than guessed at.
215	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
216	  const pathTo = (p) => byPath.get(p) ?? null;
217	  // THE TARGET SEAM (DESIGN §6.4b): which branch and pull request a run works on,
218	  // resolved from the task's declared outcome against the repo's open pull
219	  // requests. The member's delivery preference is what says whether a green
220	  // incumbent may be landed on the way; it is read once, from the same config the
221	  // hand-off reads.
222	  const resolveTargetOf = resolveTargetFor ?? ((task, at) => resolveTarget({
223	    gh, repo, taskId: `${task.pack}/${task.id}`, outcome: task.decl.expected_outcome,
224	    delivery: deliveryFor(config), now: at, log,
225	  }));
226	  const done = [];
227	  // Items this run has let go of — a lost race, a reverted claim — and must not
228	  // pick again. Without it a revert re-picks what it just returned to the queue.
229	  const standDown = new Set();
230	
231	  for (;;) {
232	    // Read live every time: the settle just made may have readied a dependent,
233	    // and another executor may have taken what was pickable a moment ago.
234	    const open = await listOpenWorkItems(gh, repo);
235	    const candidate = pickOrder(open, { taskAfter, frequencyOf, random, pathTo })
236	      .find((i) => !standDown.has(i.number));
237	    if (!candidate) break;
238	
239	    // --- claim: the verified lease ------------------------------------------
240	    await swapStatus(api, gh, repo, candidate, STATUS_READY, EXECUTING);
241	    await api.comment(gh, repo, candidate.number, claimComment({
242	      executor: executorId, runUrl, at: nowIso(),
243	    }));
244	    const comments = await api.listComments(gh, repo, candidate.number);
245	    const winner = claimWinner(comments);
246	    const mine = [...comments]
247	      .sort((a, b) => a.id - b.id)
248	      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
