252	      // strike its own claim (F24): letting go covers losing too, and a claim left
253	      // behind here outlives the winner's episode and becomes the earliest of the
254	      // NEXT one, moving the livelock one episode along.
255	      await strikeClaim(api, gh, repo, mine);
256	      standDown.add(candidate.number);
257	      log(`- #${candidate.number}: another executor holds this episode's earliest claim — leaving it to them`);
