270	    }
271	
272	    const outcome = await executeItem({
273	      api, gh, repo, root, config, schedule, byId, pathTo, item: candidate, executorId,
274	      claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
275	      resolveTargetOf,
276	    });
277	    done.push({ issue: candidate.number, outcome });
