279	    // --- the hold, between items (§15.30) -----------------------------------
280	    // Asked after the settle rather than before the pick that follows it, so a
281	    // run that had nothing more to do never spends the read. The item just
282	    // finished is untouched: suspension stops picking, never running work.
283	    if (heldNow && await heldNow()) {
284	      log(`- ${SUSPEND_ALL_VAR} is set: this drain stops here, holding nothing. Items stay exactly as they are.`);
285	      break;
286	    }
287	  }
288	  return done;
