291	// The claim id of each live item, so the post-claim verify can compare episodes.
292	// One comment read per conflicting-looking item, not per item in the repo.
293	async function withClaimIds(api, gh, repo, items, selfNumber) {
294	  const out = [];
295	  for (const i of items) {
296	    if (i.number === selfNumber || !running(i)) { out.push(i); continue; }
297	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
298	    out.push({ ...i, claimId: winner?.id ?? null });
299	  }
300	  return out;
301	}
