303	// One claimed item, from validation through to a terminal state (or a hand-off).
304	async function executeItem({
305	  api, gh, repo, root, config, schedule, byId, pathTo = () => null, item, executorId, claim,
306	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log, resolveTargetOf,
307	}) {
308	  const parsed = parseWorkItemTitle(item.title);
309	  const { taskPath } = parseWorkItemBody(item.body);
310	  // A marked issue's identity is its machine block, not its title (§16.1): the id
311	  // is whichever task owns the worker path the block names.
312	  const id = parsed ? `${parsed.pack}/${parsed.task}` : pathTo(taskPath);
313	  const task = id ? byId.get(id) : null;
314	  // The exec record joins back to the work by pack and task, which a marked issue's
315	  // human title cannot supply — so the resolved id travels with the item.
316	  item.taskId = id;
317	
318	  // --- validate in code, before anything trusts the issue ------------------
319	  if (!taskPath || (!parsed && !id)) {
320	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
321	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
322	    return 'needs-human';
323	  }
324	  if (!task) {
325	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
326	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone');
327	    return 'obsolete';
328	  }
329	  // THE SAME FACT, LEARNED LATER. The task set was built once, at the start of the
330	  // run; one run drains several items from one checkout, and an earlier item's own
331	  // work rewrites that checkout — the mount update deletes a retired task's
332	  // directory out from under the items behind it. So a task can resolve here and
333	  // not exist on disk — the same fact the branch above closes on, and it converges
334	  // the same way. Without this the run reaches code-work and spawns with a cwd that is gone
335	  // (missingbulb/Shepherd#300).
336	  if (!existsSync(task.taskDir)) {
337	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
338	      `\`${id}\` no longer exists in this checkout (\`${task.taskPath}\`) — it was removed while this run was in flight. Nothing ran. Closing obsolete.`, 'task-gone');
339	    return 'obsolete';
340	  }
341	  if (task.taskPath !== taskPath) {
342	    // A MISMATCH HAS TWO CAUSES AND ONLY ONE IS A PERSON'S PROBLEM (#1461). The guard
343	    // exists for a tampered or forged item, whose path names some OTHER task — that
344	    // parks. But an item open across a pack rename hits it too: only the title's id is
345	    // canonicalized (`parseWorkItemTitle`), so the body keeps naming the pre-rename
346	    // directory forever, and parking it strands the item AND holds the task's lane,
347	    // since nothing rewrites an item body. When the path resolves to this very task —
348	    // `taskIdFromPath` canonicalizes too — the item is merely stale, which is the
349	    // `!task` branch's verdict: close it obsolete and let the generator file a fresh
350	    // occurrence at today's path.
351	    const named = taskIdFromPath(taskPath);
352	    if (named && `${named.pack}/${named.task}` === id) {
353	      await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
354	        `This item names \`${id}\` at \`${taskPath}\`, where it no longer lives — the pack was renamed since the item `
355	        + `was filed, and the task is at \`${task.taskPath}\` now. An item's stored path is never rewritten, so this one `
356	        + 'can never run. Closing obsolete; the scheduler files a fresh occurrence at the current path.', 'task-gone');
357	      return 'obsolete';
358	    }
359	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
360	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
361	    return 'needs-human';
362	  }
363	
364	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
365	  const at = now();
366	  const fields = parseWorkItemBody(item.body);
367	  // The signals are collected FOR THIS OCCURRENCE, and the precondition judges over
368	  // it: a request item's verdict is about the issue it names, which no signal bundle
369	  // can single out on its own (DESIGN §16.4).
370	  const signals = await collectSignalsFor(task, at, item);
371	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields, at);
372	
373	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
374	  // decline is a decision about the world; one taken on an API that would not answer
375	  // is a guess, and its write-backs cannot land — for a request that would strand
376	  // the issue armed-but-queued forever, the request silently eaten. So the item
377	  // parks open in the failure lane, where the ordinary re-queue lever retries it
378	  // once the API recovers, and nothing is written to whatever it could not read.
379	  if (verdict.error) {
380	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
381	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
382	    log(`! #${item.number} ${id}: the precondition could not answer — ${verdict.error}`);
383	    return 'needs-human';
384	  }
385	
386	  if (verdict.run !== true) {
387	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
388	    // A DECLINED REQUEST IS DISARMED IN THE SAME CONVERGENCE (DESIGN §16.5).
389	    // Nothing else would: an issue left carrying `claude-queued` after its run was
390	    // refused is one no later scheduler run adopts and no person is told about, and one
391	    // whose mark — if re-applied — walks into the same refusal forever.
392	    // A LEGACY shadow item wrote its decline back to the issue it named. A marked
393	    // issue IS the item, so the decline's comment and its `rejected` status already
394	    // land where the person is looking and there is nothing to mirror (§16.5).
395	    if (fields.request && fields.request !== item.number) {
396	      await declineRequest(api, gh, repo, fields.request, item.number, plan.reason);
397	    }
398	    // A DECLINE IS A COMPLETED RUN, not a failure: the executor asked, got a
399	    // no, and closed the occurrence — so the record says `success` and the
400	    // reason sits beside it in the same comment.
401	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
402	      `The precondition declined: ${plan.reason}`
403	      + (plan.standing
404	        ? '\n\nThis task\'s next occurrence is decided at its next anchor; declined occurrences are recorded on the schedule board.'
405	        : ''), 'success');
406	    return 'obsolete';
407	  }
408	
409	  // --- code-work (unchanged contract), then converge or hand off -------------
410	  // The item's OWN Context is scope too, not decoration: an operator's parameters
411	  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
412	  // so code-work sees the union of what the item was created with and what this
413	  // occurrence's precondition added. Passing only the verdict's half is what made
414	  // a hand-created item's parameters unreachable (#974).
415	  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
416	
417	  // --- the target: which pull request this run works on (DESIGN §6.4b) ------
418	  // Decided ONCE, here, between the go and the work, and handed to both phases —
419	  // code-work as environment, the agent as item fields — so neither phase
420	  // discovers, chooses or disposes of a pull request on its own. A read the
421	  // resolver could not make is a run failure like an unanswerable precondition
422	  // (F27): an unreadable pull request list looks exactly like an empty one, and
423	  // "nothing to amend" on that evidence stacks a duplicate.
424	  const target = await resolveTargetOf(task, at);
425	  if (target.error) {
426	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
427	      `This run could not be given a target: ${target.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
428	    log(`! #${item.number} ${id}: the target could not be resolved — ${target.error}`);
429	    return 'needs-human';
430	  }
431	  log(`- #${item.number} ${id}: target — ${target.reason}`);
432	  if (target.landed) {
433	    // The previous delivery had concluded green and was landed by the resolution.
434	    // That IS this occurrence: the tree this run holds predates the merge, so the
435	    // work would re-deliver a diff already on the base. The next occurrence
436	    // converges from the moved base.
437	    await closeSuperseded({ gh, repo, numbers: target.supersedes, successor: target.landed, log });
438	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_DONE, 'completed',
439	      `Landed #${target.landed}, this task's previous delivery, which had concluded green and was never merged. `
440	      + 'The checkout this run holds predates that merge, so nothing else ran; the next occurrence converges from the moved base.', 'success');
441	    return TASK_DONE;
442	  }
443	
444	  if (task.decl.code_work) {
445	    // The work step may legitimately run for hours (§15.15). While it does, the
446	    // item's only sign of life is this beat — which is also what the scheduler run's leash
447	    // measures, so a long run is legal rather than reclaimed underneath itself.
448	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context, target }), {
449	      intervalMs: heartbeatMs,
450	      log,
451	      beat: (minutes) => api.comment(gh, repo, item.number,
452	        heartbeatComment({ executor: executorId, at: nowIso(), minutes })),
