539	// Run one task's precondition. THE only place a precondition is ever called, so a
540	// test that drives this drives what production drives — a precondition first
541	// written to take `{ signals }` passed its own direct-call test and threw on every
542	// real run, which is the failure this seam exists to make impossible.
543	//
544	// One form comes through here: the declarative `preconditions` expression, which
545	// is the only gate a task may declare (#1617). It fails LOUD by construction — a
546	// term that throws, an unknown name, an unreadable signal all return `{ error }`,
547	// a run failure the caller parks rather than a decline taken on a guess.
548	export function evaluatePrecondition(task, signals, packConfig = {}, item = null, at = null) {
549	  return evaluatePreconditions({
550	    preconditions: task.decl.preconditions,
551	    signals,
552	    config: packConfig,
553	    item,
554	    terms: task.terms,
555	    windowDays: windowDays(task),
556	    // The instant this verdict is for — the same one the signals were collected
557	    // for, so a clock-reading term and a windowed one cannot disagree about when
558	    // "now" is.
559	    now: at,
560	  });
561	}
