563	// @deprecated The write-back a refused SHADOW item's issue got — one comment saying
564	// why, and the queued label off, so the request was disarmed rather than left
565	// looking pending. Nothing writes it for an item filed under the one-issue model,
566	// where the item and the issue are the same object; it stays for the shadow items
567	// still draining, whose issue is a different one (DESIGN §16.5).
568	async function declineRequest(api, gh, repo, request, item, reason) {
569	  await api.comment(gh, repo, request,
570	    `Not implementing this: ${reason}\n\nThe queued run (#${item}) is closed and \`${QUEUED_LABEL}\` is removed. `
571	    + 'If this was wrong, mark the issue again — a request is only run when the person who opened it, or somebody who commented `/claude go`, has push access here.');
572	  await api.removeLabel(gh, repo, request, QUEUED_LABEL);
573	}
