575	// @deprecated The roll retired with #1115 — nothing writes this any more. Kept
576	// exported because bodies the fielded roll wrote are stored data: the
577	// round-trip test over this writer is what pins `parseLastVerdict`'s decode,
578	// which the migration and the dashboard still read.
579	export function rollBody(body, until, reason, at) {
580	  const stamped = withNotBefore(body, until);
581	  return withSection(stamped, LAST_VERDICT_HEADING, lastVerdictLines({ at, reason, until }));
582	}
