584	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
585	// what lets this be as short as it is. The nonce goes on the item before the call
586	// and travels in the payload, so the session can prove the fire it arrived on is
587	// the hand-off this item recorded and stop if it is not.
588	async function handOff({ api, gh, repo, item, task, id, context, result, target = null, executorId, claim, invokeAgent, config, log }) {
589	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
590	  // Every section lands in the machine's half of the body — the whole body for a
591	  // filed item, the machine block for a marked issue, whose prose is the person's.
592	  const body = editItemBody(item.body, (machine) => {
593	    let out = machine;
594	    // The target's fields first, under the task path: the branch the session
595	    // pushes to, the pull request it amends, the ones its converge supersedes.
596	    if (target) out = withTarget(out, target);
597	    if (context.length) out = withSection(out, 'Context', context);
598	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
599	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
600	    return out;
601	  });
602	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
603	
604	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, AGENT);
605	  await api.comment(gh, repo, item.number,
606	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
607	
608	  const invocation = await invokeAgent({ task, item, nonce, config });
609	  if (invocation.ok) {
610	    await api.comment(gh, repo, item.number,
611	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
612	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
613	    return 'agent';
614	  }
615	  if (invocation.answered) {
616	    // The endpoint refused, so no session exists and none will: a token, a URL or
617	    // a routine is wrong, and every future pick would be refused the same way.
618	    await converge(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN_ACTION, claim,
619	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (${requeueHint}).`);
620	    return 'needs-human';
621	  }
622	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
623	  // may have started a session. Re-queueing here is what would put two sessions on
624	  // one item, and converging to triage would kill a run that is very possibly
625	  // alive. So the item STAYS with the agent and says the outcome is unknown —
626	  // whichever way it went is then settled by a rule that already exists: a session
627	  // that started converges the item, and one that never did leaves the item silent
628	  // until the janitor's agent leash sweeps it to triage.
629	  await api.comment(gh, repo, item.number,
630	    `The agent invocation got no answer: ${invocation.error}\n\n`
631	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
632	    + 'If a session did start it will converge this item; if it did not, the janitor\'s agent leash parks it for a human within a few hours.');
633	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
634	  return 'unknown';
635	}
636	
637	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
638	// that stops owning an item without closing it — the roll, and every
639	// `needs-human` park — strikes its own claim by appending the episode marker to
640	// it. `claimWinner` already treats the last marker as the boundary, so a struck
641	// claim stops outranking anything and the next claimant wins on its first try.
642	//
643	// APPENDING rather than commenting is what lets the roll stay silent (§5): an
644	// hourly task that declines every hour adds no timeline entry. A successful
645	// hand-off deliberately does NOT strike — the episode is still live, owned by the
646	// agent session — and neither does a close, since nothing re-claims a closed item.
647	//
648	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
649	// executor that dies between the two leaves the item `task:executing` with a
650	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
651	// would leave exactly the state this fixes — parked, re-queued by a human, and
652	// unclaimable forever.
653	async function strikeClaim(api, gh, repo, claim) {
654	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
655	  await api.editComment(gh, repo, claim.id,
656	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
657	}
658	
659	// Every exit converges the item exactly once, with one comment saying what
660	// happened — the terminal-state discipline the incidents bought. The claim sits
661	// before the body so every state argument is grouped ahead of the prose.
662	//
663	// THE COMMENT CARRIES THE EXECUTION RECORD (DESIGN §6.5, §15.18). Actions logs
664	// expire, and for an agentless run — the majority — the item is the only durable
665	// trace there will ever be, so the record goes where the item is rather than into
666	// a log that ages out. The bracketed field is this item's issue number, which is
667	// the only join from a record back to the work it describes.
668	// A status of `null` writes NO record, and that is the honest answer for a park
669	// that is not a failure: the vocabulary's `success` means "ran to completion and
670	// the issue was closed" and `failed` means the run broke, so an approval park —
671	// a run that succeeded and left a PR for a person — is neither. Absence is a
672	// state of its own; inventing a fifth status is a change to stored data every
673	// decoder in the fleet would have to learn.
674	const recordFor = (item, status) => {
675	  // `item.taskId` is the resolved id — a marked issue's title names no task, so the
676	  // title parse alone would silently drop the record for every request run.
677	  const id = item.taskId ?? null;
678	  const parsed = status
679	    ? (id ? { pack: id.split('/')[0], task: id.split('/').slice(1).join('/') } : parseWorkItemTitle(item.title))
680	    : null;
681	  return parsed
682	    ? `\n\n\`\`\`\n${renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })}\n\`\`\``
683	    : '';
684	};
685	
686	// Park an item for a human. ONE label: the park IS the status, and its kind is what
687	// the human is being asked for (DESIGN §4). The two-label park it replaces could be
688	// half-applied, which was a torn state of its own.
689	async function converge(api, gh, repo, item, from, park, claim, body, status = 'failed') {
690	  await strikeClaim(api, gh, repo, claim);
691	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
692	  await swapStatus(api, gh, repo, item, from, park);
693	}
694	
695	// A close writes only to the item it holds (§15.19, reversed by §15.31 /
696	// #1373): a dependent this close may make due is released solely by the
697	// scheduler run's own readiness job, on its next hourly pass, never here.
698	async function close(api, gh, repo, item, from, outcome, stateReason, body, status) {
699	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
700	  await clearStatus(api, gh, repo, item, from);
701	  await api.addLabel(gh, repo, item.number, outcome);
702	  // A REJECTED TERMINAL IS NOT THE RUN'S TO CLOSE A MARKED ISSUE ON (§16.5): the
703	  // run's verdict is about the run, not the issue's validity, so the status stands
704	  // on the still-open issue and clearing it is the asker's lever. `done` is the
705	  // other half and closes either shape (#1489) — nothing is left to act on.
706	  if (outcome !== TASK_DONE && !isWorkItemTitle(item.title)) return;
707	  await api.closeIssue(gh, repo, item.number, stateReason);
708	}
709	
710	// --- CLI ----------------------------------------------------------------------
711	
712	async function main() {
713	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
714	  // first API call, so a held queue reads nothing and writes nothing rather than
715	  // deriving the world and then declining to act on it.
716	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
717	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
718	  const { discoverTasks } = await import('../discover.mjs');
719	  const { loadConfig, isDormant } = await import('../../../engine/checks/helpers/repo-context.mjs');
720	  const { ensureLabels } = await import('../github.mjs');
721	  const { collectSignalsForTask } = await import('./signals.mjs');
722	  const { codeWorkRunner } = await import('./code-work-run.mjs');
723	  const { agentInvoker } = await import('./invoke.mjs');
724	
725	  const root = process.cwd();
726	  const { repo, defaultBranch } = actionRepoContext();
727	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
728	  const config = loadConfig(root);
729	
730	  console.log('## Claudinite executor\n');
731	  if (isDormant(config)) {
732	    console.log('- this project declares itself dormant — nothing is picked up');
733	    return;
734	  }
735	
736	  const gh = makeGh();
737	  const { tasks, errors } = await discoverTasks(root, config);
738	  for (const e of errors) console.log(`! ${e.what}`);
739	  await ensureLabels(gh, repo, QUEUE_LABELS);
740	
741	  const runUrl = process.env.GITHUB_RUN_ID
742	    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
743	    : null;
744	
745	  const done = await runExecutor({
746	    gh, repo, root, config, tasks,
747	    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
748	    runUrl,
749	    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
750	    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
751	    invokeAgent: agentInvoker({ repo, config }),
752	    heldNow: () => readSuspendedNow(gh, repo, { log: console.log }),
753	  });
754	
755	  console.log(done.length
756	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
757	    : '- nothing ready to pick up');
758	}
759	
760	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
761	  main().catch((e) => { console.error(e); process.exit(1); });
762	}
763

